#!/usr/bin/env python3
"""Offline compiler for service-path policy bundles.

Reads JSON Lines requests on standard input and writes one JSON object per
input line.  For every in-limit request the complete-path language

    L = (union of allow rule languages) minus (union of drop rule languages)

is compiled into its canonical minimal deterministic automaton together with
per-state viability distances, and every query path is answered against it.
"""

import json
import re
import sys
from collections import deque

MAX_LINE_BYTES = 1048576
MAX_DEPTH = 64
MAX_TUPLES = 20000

ATOM_OPS = ("match", "startswith", "endswith", "contains")

ERR = {
    code: json.dumps({"ok": False, "error": code}, separators=(",", ":"))
    for code in ("E_JSON", "E_SCHEMA", "E_LIMIT", "E_COMPLEXITY")
}

# Characters that can influence the preliminary nesting scan.
_SKELETON_RE = re.compile(r'[^{}\[\]"\\]')
# Unpaired surrogate code points (invalid Unicode scalar values).
_SURROGATE_RE = re.compile("[\ud800-\udfff]")


# --------------------------------------------------------------------------
# Stage 1/2: physical limits and preliminary nesting scan
# --------------------------------------------------------------------------

def depth_exceeds(text, limit=MAX_DEPTH):
    """True when the brace/bracket nesting depth ever exceeds ``limit``.

    Double quoted strings and backslash escapes are honoured exactly as JSON
    does; delimiter kinds need not match and the depth is floored at zero.
    """
    skeleton = _SKELETON_RE.sub("", text)
    depth = 0
    in_string = False
    escaped = False
    for ch in skeleton:
        if in_string:
            if escaped:
                escaped = False
            elif ch == "\\":
                escaped = True
            elif ch == '"':
                in_string = False
        elif ch == '"':
            in_string = True
        elif ch == "{" or ch == "[":
            depth += 1
            if depth > limit:
                return True
        else:
            depth -= 1
            if depth < 0:
                depth = 0
    return False


# --------------------------------------------------------------------------
# Stage 3: JSON parsing without duplicates or forbidden constants
# --------------------------------------------------------------------------

def _reject_constant(name):
    raise ValueError("forbidden numeric constant: %s" % (name,))


def _object_without_duplicates(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError("duplicate object key: %r" % (key,))
        obj[key] = value
    return obj


def parse_json_line(text):
    return json.loads(
        text,
        parse_constant=_reject_constant,
        object_pairs_hook=_object_without_duplicates,
    )


# --------------------------------------------------------------------------
# Stage 4: schema validation
# --------------------------------------------------------------------------

def strings_are_scalars(obj):
    """Every string in the parsed document holds valid Unicode scalars."""
    if isinstance(obj, str):
        return _SURROGATE_RE.search(obj) is None
    if isinstance(obj, dict):
        for key, value in obj.items():
            if _SURROGATE_RE.search(key) is not None:
                return False
            if not strings_are_scalars(value):
                return False
        return True
    if isinstance(obj, list):
        for item in obj:
            if not strings_are_scalars(item):
                return False
        return True
    return True


def expression_ok(expr, service_set):
    if not isinstance(expr, dict):
        return False
    keys = set(expr.keys())
    op = expr.get("op")
    if not isinstance(op, str):
        return False
    if op == "true" or op == "false":
        return keys == {"op"}
    if op in ATOM_OPS:
        if keys != {"op", "path"}:
            return False
        path = expr["path"]
        if not isinstance(path, list):
            return False
        for token in path:
            if not isinstance(token, str):
                return False
            if token not in service_set:
                return False
        return True
    if op == "not":
        if keys != {"op", "arg"}:
            return False
        return expression_ok(expr["arg"], service_set)
    if op == "and" or op == "or":
        if keys != {"op", "args"}:
            return False
        args = expr["args"]
        if not isinstance(args, list):
            return False
        for arg in args:
            if not expression_ok(arg, service_set):
                return False
        return True
    return False


def schema_ok(obj):
    if not strings_are_scalars(obj):
        return False
    if not isinstance(obj, dict):
        return False
    if set(obj.keys()) != {"services", "rules", "queries"}:
        return False
    services = obj["services"]
    if not isinstance(services, list):
        return False
    service_set = set()
    for token in services:
        if not isinstance(token, str):
            return False
        if not token:
            return False
        if token in service_set:
            return False
        service_set.add(token)
    rules = obj["rules"]
    if not isinstance(rules, list):
        return False
    for rule in rules:
        if not isinstance(rule, dict):
            return False
        if set(rule.keys()) != {"action", "when"}:
            return False
        action = rule["action"]
        if not isinstance(action, str):
            return False
        if action != "allow" and action != "drop":
            return False
        if not expression_ok(rule["when"], service_set):
            return False
    queries = obj["queries"]
    if not isinstance(queries, list):
        return False
    for path in queries:
        if not isinstance(path, list):
            return False
        for token in path:
            if not isinstance(token, str):
                return False
            if token not in service_set:
                return False
    return True


# --------------------------------------------------------------------------
# Stage 5: declared size limits
# --------------------------------------------------------------------------

def sizes_ok(obj):
    services = obj["services"]
    if len(services) > 24:
        return False
    for token in services:
        if len(token) > 64:
            return False
    rules = obj["rules"]
    if len(rules) > 32:
        return False
    nodes = 0
    atoms = set()
    max_args = 0
    max_pattern = 0
    for rule in rules:
        stack = [rule["when"]]
        while stack:
            expr = stack.pop()
            nodes += 1
            if nodes > 256:
                return False
            op = expr["op"]
            if op in ATOM_OPS:
                pattern = tuple(expr["path"])
                atoms.add((op, pattern))
                if len(pattern) > max_pattern:
                    max_pattern = len(pattern)
            elif op == "not":
                stack.append(expr["arg"])
            else:
                args = expr["args"]
                if len(args) > max_args:
                    max_args = len(args)
                stack.extend(args)
    if len(atoms) > 10:
        return False
    if max_pattern > 16:
        return False
    if max_args > 32:
        return False
    queries = obj["queries"]
    if len(queries) > 256:
        return False
    total_tokens = 0
    for path in queries:
        if len(path) > 4096:
            return False
        total_tokens += len(path)
    if total_tokens > 16384:
        return False
    return True


# --------------------------------------------------------------------------
# Stage 6: atomic monitors and their synchronous product
# --------------------------------------------------------------------------

def collect_atoms(rules):
    """Distinct atoms in first-appearance order (identity is (op, path))."""
    atoms = []
    seen = set()
    for rule in rules:
        stack = [rule["when"]]
        while stack:
            expr = stack.pop()
            op = expr["op"]
            if op in ATOM_OPS:
                key = (op, tuple(expr["path"]))
                if key not in seen:
                    seen.add(key)
                    atoms.append(key)
            elif op == "not":
                stack.append(expr["arg"])
            else:
                stack.extend(expr["args"])
    return atoms


def build_monitor(op, pattern, symbol_index, alphabet):
    """Transition table for one atom monitor; returns (table, m)."""
    m = len(pattern)
    p = [symbol_index[token] for token in pattern]
    if op == "match" or op == "startswith":
        table = []
        for state in range(m + 2):
            row = [0] * alphabet
            if state < m:
                advance = state + 1
                for si in range(alphabet):
                    row[si] = advance if si == p[state] else m + 1
            elif state == m:
                fill = m if op == "startswith" else m + 1
                for si in range(alphabet):
                    row[si] = fill
            else:
                for si in range(alphabet):
                    row[si] = m + 1
            table.append(row)
        return table, m
    table = []
    for state in range(m + 1):
        row = [0] * alphabet
        if op == "contains" and state == m:
            for si in range(alphabet):
                row[si] = m
        else:
            prefix = p[:state]
            for si in range(alphabet):
                word = prefix + [si]
                best = 0
                for j in range(m if m < state + 1 else state + 1, 0, -1):
                    if word[-j:] == p[:j]:
                        best = j
                        break
                row[si] = best
        table.append(row)
    return table, m


def build_product(monitors, alphabet):
    """Reachable tuples of the synchronous product, or None above the cap."""
    count = len(monitors)
    init = (0,) * count
    states = [init]
    index = {init: 0}
    trans = []
    # columns[symbol][monitor] maps a monitor state to its successor.
    columns = []
    for si in range(alphabet):
        cols = []
        for table in monitors:
            cols.append([table[state][si] for state in range(len(table))])
        columns.append(cols)
    lookup = list.__getitem__
    append_state = states.append
    append_row = trans.append
    i = 0
    while i < len(states):
        current = states[i]
        row = []
        row_append = row.append
        for si in range(alphabet):
            cols = columns[si]
            nxt = tuple(map(lookup, cols, current))
            target = index.get(nxt)
            if target is None:
                target = len(states)
                index[nxt] = target
                append_state(nxt)
                if target >= MAX_TUPLES:
                    return None
            row_append(target)
        append_row(row)
        i += 1
    return states, trans


# --------------------------------------------------------------------------
# Boolean evaluation of rules on product states
# --------------------------------------------------------------------------

def _true(_tv):
    return True


def _false(_tv):
    return False


def compile_expr(expr, atom_index):
    op = expr["op"]
    if op == "true":
        return _true
    if op == "false":
        return _false
    if op in ATOM_OPS:
        pos = atom_index[(op, tuple(expr["path"]))]

        def atom(tv, pos=pos):
            return tv[pos]

        return atom
    if op == "not":
        inner = compile_expr(expr["arg"], atom_index)

        def negated(tv):
            return not inner(tv)

        return negated
    parts = [compile_expr(arg, atom_index) for arg in expr["args"]]
    if op == "and":
        if not parts:
            return _true
        if len(parts) == 1:
            return parts[0]

        def conjunction(tv):
            for part in parts:
                if not part(tv):
                    return False
            return True

        return conjunction
    if not parts:
        return _false
    if len(parts) == 1:
        return parts[0]

    def disjunction(tv):
        for part in parts:
            if part(tv):
                return True
        return False

    return disjunction


# --------------------------------------------------------------------------
# Minimisation (Hopcroft partition refinement)
# --------------------------------------------------------------------------

def minimize(n, alphabet, trans, accept):
    """Return a list mapping every state to its equivalence class id."""
    if n <= 1:
        return [0] * n
    if alphabet == 0:
        out = [0] * n
        for s in range(n):
            if accept[s]:
                out[s] = 1
        if all(v == 1 for v in out):
            out = [0] * n
        return out

    # Reverse adjacency, stored as arrays to keep memory flat.
    rev_head = [[-1] * n for _ in range(alphabet)]
    rev_next = [[-1] * n for _ in range(alphabet)]
    for s in range(n):
        row = trans[s]
        for a in range(alphabet):
            t = row[a]
            rev_next[a][s] = rev_head[a][t]
            rev_head[a][t] = s

    class_of = [0] * n
    accepting = [s for s in range(n) if accept[s]]
    rejecting = [s for s in range(n) if not accept[s]]
    blocks = []
    if accepting:
        blocks.append(accepting)
    if rejecting:
        blocks.append(rejecting)
    for pos, block in enumerate(blocks):
        for s in block:
            class_of[s] = pos

    while True:
        queue = deque(range(len(blocks)))
        queued = set(queue)
        while queue:
            bid = queue.popleft()
            queued.discard(bid)
            splitter = blocks[bid]
            if not splitter:
                continue
            splitter_set = set(splitter)
            for a in range(alphabet):
                heads = rev_head[a]
                links = rev_next[a]
                movers = []
                for t in splitter:
                    s = heads[t]
                    while s != -1:
                        movers.append(s)
                        s = links[s]
                if not movers:
                    continue
                by_class = {}
                for s in movers:
                    c = class_of[s]
                    bucket = by_class.get(c)
                    if bucket is None:
                        by_class[c] = [s]
                    else:
                        bucket.append(s)
                for c, moved in by_class.items():
                    block = blocks[c]
                    if len(moved) == len(block):
                        continue
                    moved_set = set(moved)
                    stay = [s for s in block if s not in moved_set]
                    new_id = len(blocks)
                    blocks.append(moved)
                    blocks[c] = stay
                    for s in moved:
                        class_of[s] = new_id
                    if c in queued:
                        queue.append(new_id)
                        queued.add(new_id)
                    elif len(moved) <= len(stay):
                        queue.append(new_id)
                        queued.add(new_id)
                    else:
                        queue.append(c)
                        queued.add(c)
        # Stability check: the partition must be a congruence now.
        representative = {}
        stable = True
        for s in range(n):
            c = class_of[s]
            sig = tuple([class_of[t] for t in trans[s]])
            known = representative.get(c)
            if known is None:
                representative[c] = sig
            elif known != sig:
                stable = False
                break
        if stable:
            return class_of

    # unreachable


# --------------------------------------------------------------------------
# Compilation of one request
# --------------------------------------------------------------------------

def compile_request(obj):
    services = obj["services"]
    rules = obj["rules"]
    queries = obj["queries"]
    alphabet = len(services)
    symbol_index = {}
    for pos, token in enumerate(services):
        symbol_index[token] = pos

    atoms = collect_atoms(rules)
    monitors = []
    finals = []
    for op, pattern in atoms:
        table, m = build_monitor(op, pattern, symbol_index, alphabet)
        monitors.append(table)
        finals.append(m)

    product = build_product(monitors, alphabet)
    if product is None:
        return ERR["E_COMPLEXITY"]
    states, trans = product
    n = len(states)

    atom_index = {}
    for pos, atom in enumerate(atoms):
        atom_index[atom] = pos
    allow_checks = [
        compile_expr(rule["when"], atom_index)
        for rule in rules if rule["action"] == "allow"
    ]
    drop_checks = [
        compile_expr(rule["when"], atom_index)
        for rule in rules if rule["action"] == "drop"
    ]

    cache = {}
    accept = [False] * n
    natoms = len(atoms)
    for pos in range(n):
        state = states[pos]
        bits = 0
        for i in range(natoms):
            if state[i] == finals[i]:
                bits |= 1 << i
        verdict = cache.get(bits)
        if verdict is None:
            tv = tuple(bool((bits >> i) & 1) for i in range(natoms))
            verdict = bool(any(f(tv) for f in allow_checks)) and \
                not any(f(tv) for f in drop_checks)
            cache[bits] = verdict
        accept[pos] = verdict

    class_of = minimize(n, alphabet, trans, accept)

    # Quotient automaton over equivalence classes.
    representative = {}
    for s in range(n):
        c = class_of[s]
        if c not in representative:
            representative[c] = s
    class_trans = {}
    class_accept = {}
    for c, s in representative.items():
        class_trans[c] = [class_of[t] for t in trans[s]]
        class_accept[c] = accept[s]

    # Canonical breadth-first numbering from the initial class.
    start_class = class_of[0]
    numbering = {start_class: 0}
    order = deque([start_class])
    next_rows = []
    next_accept = []
    while order:
        c = order.popleft()
        row = []
        for target in class_trans[c]:
            num = numbering.get(target)
            if num is None:
                num = len(numbering)
                numbering[target] = num
                order.append(target)
            row.append(num)
        next_rows.append(row)
        next_accept.append(class_accept[c])

    total = len(next_rows)

    # Shortest number of additional tokens to reach an accepting state.
    distance = [None] * total
    reverse = [[] for _ in range(total)]
    for s in range(total):
        for t in next_rows[s]:
            reverse[t].append(s)
    pending = deque()
    for s in range(total):
        if next_accept[s]:
            distance[s] = 0
            pending.append(s)
    while pending:
        u = pending.popleft()
        base = distance[u] + 1
        for v in reverse[u]:
            if distance[v] is None:
                distance[v] = base
                pending.append(v)

    results = []
    for path in queries:
        s = 0
        for token in path:
            s = next_rows[s][symbol_index[token]]
        results.append({
            "state": s,
            "allow": next_accept[s],
            "distance": distance[s],
        })

    payload = {
        "ok": True,
        "dfa": {
            "start": 0,
            "accept": next_accept,
            "next": next_rows,
            "distance": distance,
        },
        "queries": results,
    }
    return json.dumps(payload, separators=(",", ":"))


# --------------------------------------------------------------------------
# Driver
# --------------------------------------------------------------------------

def process_line(raw):
    if len(raw) > MAX_LINE_BYTES:
        return ERR["E_LIMIT"]
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError:
        return ERR["E_JSON"]
    if depth_exceeds(text):
        return ERR["E_LIMIT"]
    try:
        obj = parse_json_line(text)
    except Exception:
        return ERR["E_JSON"]
    if not schema_ok(obj):
        return ERR["E_SCHEMA"]
    if not sizes_ok(obj):
        return ERR["E_LIMIT"]
    return compile_request(obj)


def main():
    data = sys.stdin.buffer.read()
    lines = data.split(b"\n")
    if lines and lines[-1] == b"":
        lines.pop()
    out = sys.stdout
    for raw in lines:
        try:
            line = process_line(raw)
        except Exception:
            line = ERR["E_JSON"]
        out.write(line)
        out.write("\n")
    out.flush()


if __name__ == "__main__":
    main()
